public class Main {
    public static void main(String[] args) {
        // Encapsulation: each layer adds its header; decapsulation removes them.
        String[] names = {"TCP header", "IPv4 header", "Ethernet header+FCS"};
        int[] bytes = {20, 20, 18};
        int size = "GET /".length();
        System.out.println("application data: " + size + " bytes");
        for (int i = 0; i < names.length; i++) {      // going down: wrap
            size += bytes[i];
            System.out.println("add " + names[i] + " -> " + size + " bytes");
        }
        for (int i = names.length - 1; i >= 0; i--) { // going up: unwrap
            size -= bytes[i];
            System.out.println("remove " + names[i] + " -> " + size + " bytes");
        }
        // Cost: O(layers) time, O(1) extra space.
    }
}

