import java.util.*;

public class Main {
    public static void main(String[] args) {
        // A TCP connection is identified by the 5-tuple, so one server port serves many clients.
        String[] ips = {"1.1.1.1", "1.1.1.1", "2.2.2.2", "1.1.1.1"};
        int[] ports = {50000, 50001, 50000, 50000};
        Set<String> conns = new HashSet<>();
        for (int i = 0; i < ips.length; i++) {
            String t = "TCP " + ips[i] + ":" + ports[i] + " -> 10.0.0.5:443"; // the 5-tuple as a key
            boolean isNew = conns.add(t);
            System.out.println(t + " " + (isNew ? "new connection" : "same connection"));
        }
        System.out.println("connections: " + conns.size() + " on listening ports: 1");
        // Cost: O(1) per lookup with a hash set, O(connections) space.
    }
}

