import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Learning switch: learn the source MAC, forward if destination known, else flood.
        String[][] frames = {{"A","B","1"},{"B","A","2"},{"C","A","3"},{"A","B","1"}}; // src, dst, in port
        Map<String,Integer> table = new TreeMap<>();
        for (String[] f : frames) {
            int port = Integer.parseInt(f[2]);
            table.put(f[0], port);                 // learn: src lives behind this port
            List<Integer> out = new ArrayList<>();
            if (table.containsKey(f[1])) out.add(table.get(f[1]));   // known: one port only
            else for (int p = 1; p <= 4; p++) if (p != port) out.add(p); // unknown: flood
            System.out.println(f[0] + "->" + f[1] + " in:" + port + " out:" + out);
        }
        System.out.println("table: " + table);
        // Cost: O(1) per frame for the table, O(ports) when flooding; O(hosts) space.
    }
}

