#include <bits/stdc++.h>
using namespace std;
int main() {
    // Learning switch: learn the source MAC, forward if destination known, else flood.
    struct F { string src, dst; int port; };
    vector<F> frames = {{"A","B",1},{"B","A",2},{"C","A",3},{"A","B",1}};
    map<string,int> table;
    for (auto& f : frames) {
        table[f.src] = f.port;                 // learn: src lives behind this port
        vector<int> out;
        if (table.count(f.dst)) out.push_back(table[f.dst]);        // known: one port only
        else for (int p = 1; p <= 4; p++) if (p != f.port) out.push_back(p); // unknown: flood
        cout << f.src << "->" << f.dst << " in:" << f.port << " out:[";
        for (size_t i = 0; i < out.size(); i++) cout << (i ? ", " : "") << out[i];
        cout << "]\n";
    }
    cout << "table: {";
    bool first = true;
    for (auto& kv : table) { cout << (first ? "" : ", ") << kv.first << "=" << kv.second; first = false; }
    cout << "}\n";
    // Cost: O(log hosts) per frame with std::map, O(ports) when flooding.
}

