public class Main {
    public static void main(String[] args) {
        // Header overhead for TCP/IPv4/Ethernet: 20 + 20 + 14 + 4 = 58 bytes per frame.
        int overhead = 20 + 20 + 14 + 4;
        int[] payloads = {1, 100, 1000, 1460};
        for (int payload : payloads) {
            int frame = Math.max(payload + overhead, 64); // Ethernet pads to a 64-byte minimum
            System.out.println(String.format("payload %4d -> frame %4d bytes, efficiency %.1f%%",
                    payload, frame, 100.0 * payload / frame));
        }
        // Cost: O(1) per size; the point is the fixed 58-byte cost per frame.
    }
}

